#!/bin/bash
# Generated By: Claude Code (claude-opus-5-5[1m])
#
# --reap offers idle sandboxes for deletion in fzf. What it has to get right:
#   - candidates are a Stopped/Error container with its directory, a directory
#     with no container, or an sb-<hash> container with no directory, idle past
#     --older-than; a live sandbox, a young one, and a container sandbox.sh did
#     not name are never offered;
#   - an incomplete `openshell sandbox list` deletes nothing;
#   - age comes from podman's FinishedAt, surviving a container that vanishes
#     mid-inspect, else from the manifest's stamps, else (a zombie) created_at;
#   - git state is shown as columns, not used to exclude, and reading it runs
#     nothing a sandbox planted in the repo's .git/config;
#   - a pick is confirmed before anything is deleted, because fzf returns the
#     highlighted row on ENTER with nothing toggled;
#   - a failed container delete keeps the directory.
#
# Isolation: fake openshell, podman and fzf first on PATH, each failing on any
# subcommand it does not model; a scratch HOME, so ~/sandboxes is the fixture;
# GIT_CONFIG_GLOBAL=/dev/null; every reap run reads /dev/null or a here-string
# on stdin, so the confirmation never waits on a terminal.
#
# Run: tests/test-reap.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
if [[ ! -f "${WORK}/config/site.env" ]]; then
    printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
        > "${WORK}/config/site.env"
fi
SANDBOX_SH="${WORK}/scripts/sandbox.sh"

stamp() { date -u -d "-$1 days" +%Y-%m-%dT%H:%M:%SZ; }
listed() { date -u -d "-$1 days" '+%Y-%m-%d %H:%M:%S'; }
DELETE_LOG="${TMP}/deleted"
export DELETE_LOG

FAKE_BIN="${TMP}/bin"
mkdir -p "$FAKE_BIN"
# list prints $FAKE_LIST; delete logs its name, failing for $FAKE_DELETE_FAIL.
cat > "${FAKE_BIN}/openshell" <<'EOF'
#!/bin/bash
if [[ "$1 $2" == "sandbox list" ]]; then
    [[ -n "${FAKE_LIST:-}" ]] || exit 1
    printf '%s\n' "$FAKE_LIST"
elif [[ "$1 $2" == "sandbox delete" ]]; then
    [[ "$3" == "${FAKE_DELETE_FAIL:-}" ]] && exit 1
    echo "$3" >> "$DELETE_LOG"
else
    exit 1
fi
EOF
# ps lists every Id in $FAKE_INSPECT plus $FAKE_GONE, a container removed
# before inspect: like podman, inspect then prints the ids it found and fails.
cat > "${FAKE_BIN}/podman" <<'EOF'
#!/bin/bash
case "$1" in
    ps) jq -r '.[].Id' <<<"$FAKE_INSPECT"
        [[ -n "${FAKE_GONE:-}" ]] && echo "$FAKE_GONE"
        exit 0 ;;
    inspect) shift
        jq -c '[.[] | select(.Id as $i | $ARGS.positional | index($i))]' --args "$@" <<<"$FAKE_INSPECT"
        for id in "$@"; do [[ "$id" == "${FAKE_GONE:-}" ]] && exit 125; done
        exit 0 ;;
    *) exit 1 ;;
esac
EOF
# fzf: record its input, drop the header line, print rows matching $FAKE_PICK.
# FAKE_FZF_HIGHLIGHT is ENTER with nothing toggled: the first row comes back.
cat > "${FAKE_BIN}/fzf" <<'EOF'
#!/bin/bash
if [[ -n "${FAKE_FZF_HIGHLIGHT:-}" ]]; then
    tee "$FZF_INPUT" | sed -n 2p
else
    tee "$FZF_INPUT" | tail -n +2 | grep -E "${FAKE_PICK:-^$}" || true
fi
exit "${FAKE_FZF_RC:-0}"
EOF
export FZF_INPUT="${TMP}/fzf-input"
chmod +x "${FAKE_BIN}"/*
export PATH="${FAKE_BIN}:${PATH}"
export GIT_CONFIG_GLOBAL=/dev/null

FAKE_HOME="${TMP}/home"
SB="${FAKE_HOME}/sandboxes"
# The directory's own mtime is left at now on purpose: age must come from the
# manifest's stamps, since every manifest rewrite bumps the directory too.
make_sandbox() {
    local name="$1" created_days="$2"
    mkdir -p "${SB}/${name}"
    printf '{"name":"%s","openshell_name":"sb-%s","profile":"personal","created":"%s","repos":{}}' \
        "$name" "$name" "$(stamp "$created_days")" > "${SB}/${name}/manifest.json"
}

TRAP_RAN="${TMP}/trap-ran"
reset_fixture() {
    rm -rf "$SB" "$DELETE_LOG" "$TRAP_RAN"
    # oldstop's manifest says 90d and podman says 60d: the age shown tells
    # which source won.
    make_sandbox oldstop 90
    make_sandbox youngstop 60
    make_sandbox noinspect 75
    make_sandbox orphan 60
    make_sandbox youngorphan 2
    make_sandbox live 60
    # orphan carries one repo with an untracked file, a stash and a commit no
    # remote has: 1 dirty, 1 stash, 2 unpushed (the stash base and the next).
    local repo="${SB}/orphan/repo"
    git init -q "$repo"
    git -C "$repo" -c user.name=t -c user.email=t@t commit -q --allow-empty -m one
    echo a > "${repo}/f"
    git -C "$repo" add f
    git -C "$repo" -c user.name=t -c user.email=t@t commit -q -m two
    echo b > "${repo}/f"
    git -C "$repo" -c user.name=t -c user.email=t@t stash -q
    echo c > "${repo}/untracked"
    # What a sandbox session can leave in a repo --download brings back: an
    # fsmonitor and a clean filter, each of which plain `git status` runs. f is
    # made stat-dirty so the filter has something to clean.
    printf '#!/bin/sh\ntouch %s\n' "$TRAP_RAN" > "${TMP}/fsmonitor"
    chmod +x "${TMP}/fsmonitor"
    git -C "$repo" config core.fsmonitor "${TMP}/fsmonitor"
    git -C "$repo" config filter.evil.clean "touch ${TRAP_RAN}; cat"
    git -C "$repo" config filter.evil.required true
    echo '* filter=evil' > "${repo}/.gitattributes"
    touch -d '+1 min' "${repo}/f"
}

export FAKE_LIST
FAKE_LIST="$(jq -nc --arg c "$(listed 60)" --arg rz "$(listed 50)" '{next_page_token: "", sandboxes: [
    {name: "sb-oldstop", phase: "Stopped", created_at: $c},
    {name: "sb-youngstop", phase: "Stopped", created_at: $c},
    {name: "sb-noinspect", phase: "Stopped", created_at: $c},
    {name: "sb-live", phase: "Ready", created_at: $c},
    {name: "sb-0123456789ab", phase: "Stopped", created_at: $c},
    {name: "sb-00000000000a", phase: "Stopped", created_at: $c},
    {name: "sb-0000000000bb", phase: "Ready", created_at: $rz},
    {name: "handmade", phase: "Stopped", created_at: $c}]}')"
export FAKE_INSPECT
FAKE_INSPECT="$(jq -nc --arg o "$(stamp 60)" --arg y "$(stamp 2)" '[
    {Id: "c1", Config: {Labels: {"openshell.ai/sandbox-name": "sb-oldstop"}}, State: {FinishedAt: $o}},
    {Id: "c2", Config: {Labels: {"openshell.ai/sandbox-name": "sb-youngstop"}}, State: {FinishedAt: $y}},
    {Id: "c3", Config: {Labels: {"openshell.ai/sandbox-name": "sb-0123456789ab"}}, State: {FinishedAt: $o}},
    {Id: "c4", Config: {Labels: {"openshell.ai/sandbox-name": "sb-00000000000a"}}, State: {FinishedAt: $y}},
    {Id: "c5", Config: {Labels: {"openshell.ai/sandbox-name": "handmade"}}, State: {FinishedAt: $o}}]')"

fail=0
# stdin is never the terminal: EOF at the confirmation is a "no".
reap() { HOME="$FAKE_HOME" bash "$SANDBOX_SH" --reap "$@" 2>&1 </dev/null; }
reap_yes() { HOME="$FAKE_HOME" bash "$SANDBOX_SH" --reap 2>&1 <<<y; }
row() { grep -E "^[0-9]+	$1 " "$FZF_INPUT"; }

# --- the fixture's planted git config is armed: plain status runs it ---
reset_fixture
git -C "${SB}/orphan/repo" status --porcelain >/dev/null 2>&1 || true
[[ -f "$TRAP_RAN" ]] || { echo "FAIL: fixture trap did not fire under plain git status" >&2; fail=1; }

# --- the picker shows exactly the candidates, with ages and git columns ---
reset_fixture
reap --dryrun >/dev/null || true
for want in 'oldstop +stopped +60d' 'noinspect +stopped +75d' 'orphan +orphan-dir +60d' \
        'sb-0123456789ab +zombie +60d' 'sb-0000000000bb +zombie +50d'; do
    grep -qE "	${want} " "$FZF_INPUT" || { echo "FAIL: picker missing: ${want}" >&2; fail=1; }
done
for never in youngstop youngorphan live sb-00000000000a handmade; do
    row "$never" >/dev/null && { echo "FAIL: picker offered ${never}" >&2; fail=1; }
done
grep -qE '^-	NAME +GROUP +AGE +PROFILE +DIRTY +STASH +UNPUSHED' "$FZF_INPUT" \
    || { echo "FAIL: picker header line missing" >&2; fail=1; }
row orphan | grep -qE 'orphan-dir +60d +personal +1 +1 +2$' \
    || { echo "FAIL: orphan git columns wrong: $(row orphan)" >&2; fail=1; }
[[ ! -f "$TRAP_RAN" ]] || { echo "FAIL: reading git state ran a planted fsmonitor or filter" >&2; fail=1; }

# --- --older-than widens the window for every age source ---
reap --dryrun --older-than 1 >/dev/null || true
for want in 'youngstop +stopped' 'youngorphan +orphan-dir' 'sb-00000000000a +zombie'; do
    grep -qE "	${want} " "$FZF_INPUT" || { echo "FAIL: --older-than 1 did not offer: ${want}" >&2; fail=1; }
done

# --- a container gone mid-inspect costs only its own FinishedAt ---
reset_fixture
FAKE_GONE=gone reap --dryrun >/dev/null || true
row oldstop | grep -qE 'stopped +60d ' \
    || { echo "FAIL: one vanished container lost the others' FinishedAt: $(row oldstop)" >&2; fail=1; }

# --- ENTER with nothing toggled returns the highlighted row: confirm first ---
reset_fixture
out="$(FAKE_FZF_HIGHLIGHT=1 reap || true)"
[[ ! -f "$DELETE_LOG" && -d "${SB}/oldstop" && -d "${SB}/noinspect" && -d "${SB}/orphan" ]] \
    || { echo "FAIL: an unconfirmed pick deleted something" >&2; fail=1; }
grep -q "Deleted" <<<"$out" && { echo "FAIL: an unconfirmed pick reported a delete" >&2; fail=1; }
FAKE_PICK='oldstop' HOME="$FAKE_HOME" bash "$SANDBOX_SH" --reap <<<n >/dev/null 2>&1 || true
[[ -d "${SB}/oldstop" ]] || { echo "FAIL: answering n deleted the pick" >&2; fail=1; }

# --- a confirmed pick deletes only what was picked: container, then directory ---
reset_fixture
out="$(FAKE_PICK='oldstop|	orphan ' reap_yes || true)"
# orphan's delete reaches openshell too: allow_missing makes it a no-op there.
[[ "$(sort "$DELETE_LOG" 2>/dev/null | tr '\n' ' ')" == "sb-oldstop sb-orphan " ]] \
    || { echo "FAIL: deleted containers: $(cat "$DELETE_LOG" 2>/dev/null)" >&2; fail=1; }
[[ ! -d "${SB}/oldstop" && ! -d "${SB}/orphan" ]] \
    || { echo "FAIL: picked directories not removed" >&2; fail=1; }
[[ -d "${SB}/youngstop" && -d "${SB}/live" && -d "${SB}/youngorphan" ]] \
    || { echo "FAIL: unpicked directories removed" >&2; fail=1; }
grep -qx "Deleted oldstop" <<<"$out" && grep -qx "Deleted orphan" <<<"$out" \
    || { echo "FAIL: post-report missing: ${out}" >&2; fail=1; }

# --- nothing picked: nothing deleted, nothing printed ---
reset_fixture
out="$(reap || true)"
[[ -z "$out" && ! -f "$DELETE_LOG" ]] \
    || { echo "FAIL: empty pick printed or deleted: ${out}" >&2; fail=1; }

# --- Esc in fzf is an empty pick; an fzf error is a failure, not an empty pick ---
reset_fixture
FAKE_FZF_RC=130 reap >/dev/null || { echo "FAIL: Esc in fzf reported failure" >&2; fail=1; }
if FAKE_FZF_RC=2 FAKE_PICK='.' reap >/dev/null; then
    echo "FAIL: an fzf error read as success" >&2
    fail=1
fi
[[ -d "${SB}/orphan" && ! -f "$DELETE_LOG" ]] \
    || { echo "FAIL: fzf error deleted something" >&2; fail=1; }

# --- a zombie pick deletes the container and touches no directory ---
reset_fixture
FAKE_PICK='sb-0123456789ab' reap_yes >/dev/null || true
[[ "$(cat "$DELETE_LOG" 2>/dev/null)" == "sb-0123456789ab" ]] \
    || { echo "FAIL: zombie not deleted" >&2; fail=1; }

# --- a failed container delete keeps the directory and reports ---
reset_fixture
out="$(FAKE_DELETE_FAIL=sb-oldstop FAKE_PICK='oldstop' reap_yes || true)"
[[ -d "${SB}/oldstop" ]] || { echo "FAIL: directory removed after failed delete" >&2; fail=1; }
grep -q "could not delete sb-oldstop" <<<"$out" || { echo "FAIL: failure not reported: ${out}" >&2; fail=1; }
grep -q "Deleted oldstop" <<<"$out" && { echo "FAIL: failed delete reported as deleted" >&2; fail=1; }

# --- --all takes every candidate, dirty included; --dryrun deletes nothing ---
reset_fixture
out="$(reap --all --dryrun || true)"
for want in 'openshell sandbox delete sb-oldstop' 'openshell sandbox delete sb-0123456789ab' \
        "rm -rf ${SB}/oldstop" "rm -rf ${SB}/orphan"; do
    grep -qF "[dryrun]: ${want}" <<<"$out" || { echo "FAIL: --all --dryrun missing: ${want}" >&2; fail=1; }
done
[[ -d "${SB}/orphan" && ! -f "$DELETE_LOG" ]] \
    || { echo "FAIL: --dryrun deleted something" >&2; fail=1; }

# --- an incomplete list deletes nothing ---
reset_fixture
for bad in "$(jq -c '.next_page_token = "x"' <<<"$FAKE_LIST")" ""; do
    if FAKE_LIST="$bad" reap --all >/dev/null; then
        echo "FAIL: --reap succeeded on an incomplete list" >&2
        fail=1
    fi
    [[ -d "${SB}/orphan" && ! -f "$DELETE_LOG" ]] \
        || { echo "FAIL: incomplete list deleted something" >&2; fail=1; }
done

# --- --delete: dryrun keeps the directory; a failed container delete keeps it ---
reset_fixture
HOME="$FAKE_HOME" bash "$SANDBOX_SH" --delete orphan --dryrun >/dev/null 2>&1 || true
[[ -d "${SB}/orphan" ]] || { echo "FAIL: --delete --dryrun removed the directory" >&2; fail=1; }
if FAKE_DELETE_FAIL=sb-orphan HOME="$FAKE_HOME" bash "$SANDBOX_SH" --delete orphan >/dev/null 2>&1; then
    echo "FAIL: --delete succeeded when openshell failed" >&2
    fail=1
fi
[[ -d "${SB}/orphan" ]] || { echo "FAIL: --delete removed the directory after a failed container delete" >&2; fail=1; }
HOME="$FAKE_HOME" bash "$SANDBOX_SH" --delete orphan >/dev/null 2>&1 \
    || { echo "FAIL: --delete of a directory with no container failed" >&2; fail=1; }
[[ ! -d "${SB}/orphan" ]] || { echo "FAIL: --delete kept the directory" >&2; fail=1; }

# --- the zombie pattern accepts what short_name() makes, and nothing longer ---
(
    # shellcheck disable=SC1091
    source "${WORK}/scripts/lib.sh"
    is_our_short_name "$(short_name any-sandbox)" || { echo "FAIL: is_our_short_name rejects short_name output" >&2; exit 1; }
    ! is_our_short_name "sb-0123456789abc" || { echo "FAIL: is_our_short_name accepts 13 hex digits" >&2; exit 1; }
    ! is_our_short_name "handmade" || { echo "FAIL: is_our_short_name accepts a plain name" >&2; exit 1; }
) || fail=1

# --- rejections ---
if HOME="$FAKE_HOME" bash "$SANDBOX_SH" --older-than 3 --dryrun >/dev/null 2>&1; then
    echo "FAIL: --older-than without --reap was accepted" >&2
    fail=1
fi
if HOME="$FAKE_HOME" bash "$SANDBOX_SH" --reap --older-than x >/dev/null 2>&1; then
    echo "FAIL: non-numeric --older-than was accepted" >&2
    fail=1
fi

[[ $fail -eq 0 ]] && echo "all --reap checks passed"
exit $fail
